import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Engine and financial core audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/ENGINE-CORE.html"}],["meta",{"property":"og:title","content":"Engine and financial core audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/ENGINE-CORE.html"}],["meta",{"name":"twitter:title","content":"Engine and financial core audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/ENGINE-CORE.md","filePath":"audits/ENGINE-CORE.md","lastUpdated":1794184492000}`),a={name:`audits/ENGINE-CORE.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="engine-and-financial-core-audit" tabindex="-1">Engine and financial core audit <a class="header-anchor" href="#engine-and-financial-core-audit" aria-label="Permalink to “Engine and financial core audit”">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Reviewed the configuration boundary, account/FD models, interest calculation, cash-flow generation, event normalization, outflow handling, provenance, simulation result construction and runtime result assembly.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h2><h3 id="eng-01-—-installment-cash-flows-can-occur-after-contractual-maturity" tabindex="-1">ENG-01 — Installment cash flows can occur after contractual maturity <a class="header-anchor" href="#eng-01-—-installment-cash-flows-can-occur-after-contractual-maturity" aria-label="Permalink to “ENG-01 — Installment cash flows can occur after contractual maturity”">​</a></h3><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js#L101-L109" target="_blank" rel="noreferrer">src/core/models.js L101-L109</a>.</p><p>The installment branch appends each date generated from the payout interval and stops only when the date is greater than or equal to maturity. It then returns those dates unchanged. If the interval does not divide the tenor, the last date is later than maturity. For example, a five-month FD with a two-month payout interval generates months 2, 4 and 6. A payout interval longer than the tenor also produces a single cash flow after maturity.</p><p><strong>Impact:</strong> the simulation can leave principal/interest unavailable beyond the product&#39;s stated maturity, and a product can pass the maturity-within-horizon filter while its final installment falls outside the simulation horizon.</p><p><strong>Recommendation:</strong> clamp the final installment date to maturity, or reject unsupported payout/tenor combinations at catalogue load time. Add regression cases for 5m/2m, 5m/6m and exact-divisor schedules. Verify that all generated cash flows satisfy <code>date &lt;= maturityDate(start)</code>.</p><h3 id="eng-02-—-leap-year-calculation-is-a-start-year-denominator-not-a-clearly-specified-day-count-convention" tabindex="-1">ENG-02 — Leap-year calculation is a start-year denominator, not a clearly specified day-count convention <a class="header-anchor" href="#eng-02-—-leap-year-calculation-is-a-start-year-denominator-not-a-clearly-specified-day-count-convention" aria-label="Permalink to “ENG-02 — Leap-year calculation is a start-year denominator, not a clearly specified day-count convention”">​</a></h3><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/interest.js#L3-L18" target="_blank" rel="noreferrer">src/core/interest.js L3-L18</a>; <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js#L79-L83" target="_blank" rel="noreferrer">src/core/models.js L79-L83</a>.</p><p>When <code>actual_leap_year</code> is enabled, <code>getYearBaseDays</code> selects 365 or 366 from the calendar year of <code>onDate</code>. <code>calcInterest</code> then applies that one denominator to every day in the interval. A cumulative FD spanning multiple calendar years is not split into yearly accrual segments. A tenor starting in a non-leap year and crossing a leap year therefore uses 365 throughout; a tenor starting in a leap year and crossing a non-leap year uses 366 throughout.</p><p><strong>Impact:</strong> results can differ from a bank&#39;s actual/actual, actual/365, actual/366 or other contract-specific basis. The label “Actual leap-year basis” does not make the precise convention clear.</p><p><strong>Recommendation:</strong> define the supported day-count convention explicitly and align the UI/report wording with it. If the intended convention is actual/actual, accrue each calendar-year segment using that year&#39;s denominator. If it is start-year basis, document that and verify it against representative bank terms. Add tests for 1m, 12m and multi-year FDs crossing 29 February in both directions.</p><h3 id="eng-03-—-financial-invariants-are-mostly-distributed-across-constructors-and-runtime-code" tabindex="-1">ENG-03 — Financial invariants are mostly distributed across constructors and runtime code <a class="header-anchor" href="#eng-03-—-financial-invariants-are-mostly-distributed-across-constructors-and-runtime-code" aria-label="Permalink to “ENG-03 — Financial invariants are mostly distributed across constructors and runtime code”">​</a></h3><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/config-schema.js" target="_blank" rel="noreferrer">config-schema.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js" target="_blank" rel="noreferrer">configuration.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js" target="_blank" rel="noreferrer">models.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/simulation-runtime.js" target="_blank" rel="noreferrer">simulation-runtime.js</a>.</p><p>The boundary validation is reasonably strict, but some model invariants still rely on catalogue quality or calling conventions. Examples include positive FD tenor/rate assumptions, the exact meaning of an installment payout schedule, and the selected leap-year/day-count basis. The CSV loader accepts a zero minimum amount and finite but negative rates; the FD model&#39;s period parser accepts zero-length periods.</p><p><strong>Impact:</strong> a malformed or future catalogue row can reach the calculation model with a structurally valid but financially implausible term.</p><p><strong>Recommendation:</strong> centralize product-term validation in the FDOption construction/load boundary: positive tenor, explicit allowed rate range, positive minimum amount where required, payout interval validity, payout schedule bounds, and consistent age/segment metadata. Keep exceptions for legitimate bank products explicit rather than silently accepting invalid values.</p><h3 id="eng-04-—-ait-is-supplied-as-a-fixed-10-engine-assumption" tabindex="-1">ENG-04 — AIT is supplied as a fixed 10% engine assumption <a class="header-anchor" href="#eng-04-—-ait-is-supplied-as-a-fixed-10-engine-assumption" aria-label="Permalink to “ENG-04 — AIT is supplied as a fixed 10% engine assumption”">​</a></h3><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js#L207-L213" target="_blank" rel="noreferrer">src/core/configuration.js L207-L213</a>.</p><p>The validated configuration returns <code>ait_rate: 0.10</code>; the input schema exposes only an enable/disable switch, not a rate or effective date.</p><p><strong>Impact:</strong> tax rules can change, differ by product or customer, and may include exemptions. A fixed rate can become stale without any obvious indication in a saved scenario or report.</p><p><strong>Recommendation:</strong> make tax assumptions explicit and versioned: rate, effective date, source/reference, applicability and product-level exemptions if supported. At minimum, print the applied AIT rate and an “assumption—verify current tax treatment” note in the report. Do not add tax-exempt catalogue products until the model can enforce their treatment.</p><h3 id="eng-05-—-the-end-value-contract-is-not-explicit-about-outflows" tabindex="-1">ENG-05 — The end-value contract is not explicit about outflows <a class="header-anchor" href="#eng-05-—-the-end-value-contract-is-not-explicit-about-outflows" aria-label="Permalink to “ENG-05 — The end-value contract is not explicit about outflows”">​</a></h3><p>See <a href="./REPORTING-OUTPUTS.html#fin-01-final-value-is-not-the-closing-portfolio-value">Reporting and outputs</a>.</p><p>The engine has both contributed-capital/return arithmetic and ending cash/liability measures. They should have distinct names and contracts. Do not collapse them into one ambiguous “final value” field.</p><h2 id="positive-observations" tabindex="-1">Positive observations <a class="header-anchor" href="#positive-observations" aria-label="Permalink to “Positive observations”">​</a></h2><ul><li>Dates are parsed as strict ISO calendar dates and normalized to UTC-midnight values in <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/dates.js" target="_blank" rel="noreferrer">dates.js</a>.</li><li>The configuration schema rejects unknown top-level, account, schedule and strategy-setting properties.</li><li>Outflow policies are explicit (<code>strict</code>, <code>defer</code>, <code>best_effort</code>) and schedule validation checks account references and date bounds.</li><li>Balance provenance is separated into principal, uncredited interest and counted interest, which supports the goal-credit accounting model.</li><li>The runtime validates account/provenance reconciliation before committing goal-mode state transitions.</li><li>Transfer-fee configuration can use bank-specific same-bank and domestic inter-bank fees plus directed custom overrides.</li></ul><h2 id="tests-to-add" tabindex="-1">Tests to add <a class="header-anchor" href="#tests-to-add" aria-label="Permalink to “Tests to add”">​</a></h2><ul><li>Irregular installment payout periods and the final-payment/maturity invariant.</li><li>Actual/actual versus actual/365 cross-year fixtures with expected bank-contract values.</li><li>Zero/negative tenor, rate, minimum amount and payout interval validation.</li><li>Outflow scenarios proving the distinction between contributed capital, paid withdrawals, outstanding liabilities and closing assets.</li><li>AIT rate/effective-date and tax-exempt product fixtures.</li></ul>`,33)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};